const K_ON_S01E01_LESSON = {"video":{"key":"k_on_s01e01","series":"K-On!","seriesIcon":"🎸","episodeTitle":"K-On! · Tập 1","icon":"🎸","title":"🎸 K-On! · Tập 1","src":"video/k_on_s01e01-web-v1.mp4","storageKey":"kino_calibrated_k_on_s01e01_v1","syncKey":"vokabelgo_kino_perfected_k_on_s01e01","progressKey":"vokabelgo_kino_progress_k_on_s01e01","fullDurationStr":"24:12","flashcardDeck":"🎬 Video: K-On! – Tập 1"},"chapterData":{"title":"K-On! · Tập 1","catalogTitle":"K-On! · Tập 1","series":"K-ON! · TẬP 1","summary":"Yui muốn tìm một câu lạc bộ để tham gia, nhưng lại tưởng “nhạc nhẹ” nghĩa là dễ chơi. Một cuộc gặp có trà, bánh và vài hiểu lầm đưa cô đến với ban nhạc mới. Những đoạn chưa rõ lời thoại sẽ tạm để trống phụ đề.","levelLabel":"Gợi ý A2–B1","defaultMode":"light","practiceModeVersion":1,"contentVersion":1,"storageKey":"vokabelgo_kino_chapters_v1_k_on_s01e01","legacyKey":"vokabelgo_kino_progress_k_on_s01e01","legacyCount":0,"cueCount":239,"vocabularyCount":16,"chapters":[{"title":"Yui vẫn chưa chọn được câu lạc bộ","icon":"🌅","start":0,"end":277.52,"picks":[1100003,1100006,1100008,1100009,1100011],"goal":"Lời thoại sinh hoạt buổi sáng, cách nói về dự định và nỗi phân vân khi chọn câu lạc bộ.","practiceUsage":{"1100003":"Mở đầu một cột mốc mới: 'Ab heute bin ich …' = Từ hôm nay tôi là…","1100006":"'immer noch nicht' = vẫn chưa…; câu hỏi gián tiếp với 'in welchem'","1100008":"'Es wird Zeit' = đã đến lúc phải…; 'bereits vor zwei Wochen' = đã từ hai tuần trước","1100009":"'eine Niete sein' = dở tệ ở mảng nào đó (cách nói tự trào)","1100011":"Câu điều kiện với 'wenn' và chủ ngữ chung 'man'"}},{"title":"Nhạc nhẹ mà sắp tan rã?","icon":"🎵","start":278.52,"end":441.02,"picks":[1100018,1100019,1100022,1100024,1100030],"goal":"Cách thông báo nguy cơ giải tán, điền đơn, nhờ vả lịch sự và khen ngợi.","practiceUsage":{"1100018":"'sich entscheiden' + zu-Infinitiv = quyết định làm gì","1100019":"'ausfüllen' = điền đơn; 'schon' = đã… rồi (Perfekt)","1100022":"'genauer gesagt' = nói chính xác hơn; 'kurz vor' = ngay trước/sắp","1100024":"Bị động 'wird aufgelöst' + hạn chót 'bis Ende des Monats'","1100030":"'bildschön' = đẹp tuyệt trần; câu hỏi đuôi 'findest du nicht?'"}},{"title":"Rủ được một người, thiếu thêm một","icon":"🎹","start":441.02,"end":611.51,"picks":[1100081,1100082,1100084,1100085,1100086,1100106],"goal":"Thuyết phục người khác gia nhập, nhượng bộ 'zwar … aber', khai mạc cuộc họp và gọi món.","practiceUsage":{"1100081":"'scheinen … zu sein' = có vẻ như…","1100082":"Nhượng bộ 'zwar … aber' = tuy… nhưng","1100084":"Khi vui mừng nhận lời giúp đỡ: “Tuyệt quá, cảm ơn cậu!”","1100085":"Khi thông báo nhóm chỉ còn thiếu thêm một người nữa.","1100086":"'als … zählen' = tính ai đó là…","1100106":"Công thức trang trọng 'Hiermit ist … eröffnet' = xin tuyên bố khai mạc"}},{"title":"Yui tưởng nhạc nhẹ là dễ chơi","icon":"🗓️","start":611.51,"end":776.5,"picks":[1100114,1100115,1100135,1100144,1100154],"goal":"Đề xuất kế hoạch chiêu mộ, nói về sở thích và thông báo có người mới quan tâm.","practiceUsage":{"1100114":"'so etwas wie' = kiểu như…","1100115":"'spendieren' = chiêu đãi, mời; 'bei den Hausaufgaben helfen' = giúp làm bài tập","1100135":"'klingen' = nghe có vẻ; 'nicht gerade' = không hẳn là…","1100144":"'es gibt' + Akkusativ = có thêm một…","1100154":"'nach etwas klingen' = nghe như là…"}},{"title":"Cao thủ guitar… hay hiểu lầm?","icon":"🍰","start":776.5,"end":1007.2,"picks":[1100162,1100163,1100184,1100196,1100201,1100211],"goal":"Chào đón khách, khó mở lời thú nhận, và mẫu câu điều kiện trái thực tế ở thì quá khứ.","practiceUsage":{"1100162":"'kneifen' (lóng) = chuồn, né tránh","1100163":"'kommen und gehen, wann du willst' = đến đi tùy thích","1100184":"Chúc ăn ngon: 'Lass es dir gut schmecken'","1100196":"'Es gibt nur zwei Arten von…' = chỉ có hai loại… (câu nói đùa nổi tiếng)","1100201":"Konjunktiv II quá khứ: 'hätten … gefunden, wäre … aufgelöst worden' = nếu không… thì đã…","1100211":"Nói mình không làm được: 'Geht nicht. Ich weiß nicht, wie.'"}},{"title":"Giữ Yui lại bằng trà và bánh","icon":"☕","start":1007.2,"end":1200,"picks":[1100216,1100218,1100223,1100236,1100245,1100248,1100252],"goal":"Thuyết phục ở lại, nói về sở thích bằng 'auf etwas stehen', và xin lỗi chân thành. (Cuối chương là phần ban nhạc biểu diễn thử — đã vào exclusions.)","practiceUsage":{"1100216":"'auf keinen Fall' = tuyệt đối không","1100218":"'umstimmen' = thuyết phục ai đổi ý","1100223":"Thành ngữ 'anbeißen' = cắn câu (nghĩa đen lẫn nghĩa bóng)","1100236":"'auf etwas stehen' = mê mẩn thứ gì (khẩu ngữ)","1100245":"'faulenzen' = lười biếng nằm dài","1100248":"'obwohl' = mặc dù; 'es ernst meinen' = nghiêm túc với việc gì","1100252":"'wenigstens' = ít nhất; 'bevor' = trước khi"}},{"title":"Chơi chưa giỏi, nhưng vui là được","icon":"🎸","start":1200,"end":1265.16,"picks":[1100256,1100259,1100260,1100273,1100274],"goal":"Nhận xét thẳng thắn mà vẫn tinh tế, và cách đổi ý bằng 'sich etwas überlegen'.","practiceUsage":{"1100256":"'Mir fehlen die Worte' = tôi không biết nói gì nữa","1100259":"'Spaß an etwas haben' = thấy vui với việc gì","1100260":"'sich etwas überlegen' = suy nghĩ lại, đổi ý","1100273":"'jdm. etwas beibringen' = dạy ai điều gì; mệnh đề quan hệ với 'was'","1100274":"Trấn an bạn bằng một câu ngắn, tự nhiên: “Đừng lo.”"}},{"title":"500 yên có mua nổi guitar?","icon":"🎬","start":1265.98,"end":1451.744,"picks":[1100278,1100282,1100284,1100285,1100286,1100288,1100289],"goal":"Kể lại tin vui cho bạn thân, hỏi giá cả bằng 'man kriegt', và lời dẫn kết tập. (Giữa chương là bài hát kết thúc — đã vào exclusions.)","practiceUsage":{"1100278":"Khi bất ngờ vì bạn đã thật sự tham gia một hoạt động.","1100282":"Khi phản ứng vì cảm thấy mình bị trêu hoặc bị xem nhẹ.","1100284":"Kể lại lời đề nghị dạy mình một kỹ năng mới.","1100285":"'Ist dir klar, …?' = cậu có hiểu… không?","1100286":"Khi nói ai đó cần tự mua một món đồ: “Du musst dir … kaufen.”","1100288":"Trả lời ngắn gọn tự nhiên: 'Glaube ich kaum' = tớ không tin đâu","1100289":"'man kriegt' = người ta mua được… (cách nói xuôi miệng)"}}]},"flashcards":[{"id":"vk_k_on_s01e01_eine_niete_sein","term":"eine Niete sein","meaning":"dở tệ, vụng về ở một mảng nào đó","grammar":"Cụm cố định: sein + im/in + lĩnh vực (im Sport, in Mathe)","example":"Aber du weißt doch, im Sport bin ich eine Niete und künstlerische Sachen sind so gar nicht mein Ding.","exampleVi":"Nhưng cậu biết mà, thể thao thì tớ là đứa dở tệ, còn mấy thứ nghệ thuật thì chẳng hợp với tớ chút nào.","note":"Yui tự trào về khả năng thể thao của mình.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100009,"sourceUrl":"?kino=kon&part=1"},{"id":"vk_k_on_s01e01_sich_entscheiden","term":"sich entscheiden","meaning":"quyết định (sau khi cân nhắc)","grammar":"Động từ phản thân; thường đi với zu-Infinitiv hoặc für + Akkusativ","example":"Ich hab mich entschieden Mitglied im Literaturclub zu werden.","exampleVi":"Tớ đã quyết định sẽ vào câu lạc bộ văn học.","note":"Mio dùng khi tuyên bố vào câu lạc bộ văn học.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100018,"sourceUrl":"?kino=kon&part=2"},{"id":"vk_k_on_s01e01_das_anmeldeformular_ausfullen","term":"das Anmeldeformular ausfüllen","meaning":"điền đơn đăng ký","grammar":"ausfüllen là động từ tách được; Perfekt: hat ausgefüllt","example":"Ich hab das Anmeldeformular schon ausgefüllt.","exampleVi":"Tớ đã điền xong đơn đăng ký rồi.","note":"'schon ausgefüllt' = đã điền xong rồi.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100019,"sourceUrl":"?kino=kon&part=2"},{"id":"vk_k_on_s01e01_aufgelost_werden","term":"aufgelöst werden","meaning":"bị giải tán (câu lạc bộ, tổ chức)","grammar":"Vorgangspassiv: werden + Partizip II (wird aufgelöst)","example":"Wenn bis Ende des Monats nicht vier neue Schüler Mitglied werden, wird er aufgelöst.","exampleVi":"Nếu đến cuối tháng không có bốn học sinh mới gia nhập, câu lạc bộ sẽ bị giải tán.","note":"Từ khóa xuyên suốt tập: nguy cơ của câu lạc bộ nhạc nhẹ.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100024,"sourceUrl":"?kino=kon&part=2"},{"id":"vk_k_on_s01e01_bildschon","term":"bildschön","meaning":"đẹp tuyệt trần","grammar":"Tính từ ghép: das Bild + schön","example":"Sie ist bildschön, findest du nicht?","exampleVi":"Cô ấy đẹp tuyệt trần, cậu có thấy thế không?","note":"Ritsu dùng để khen cô Sawako.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100030,"sourceUrl":"?kino=kon&part=2"},{"id":"vk_k_on_s01e01_ein_hoffnungsloser_fall","term":"ein hoffnungsloser Fall","meaning":"trường hợp hết thuốc chữa, vô vọng","grammar":"Cụm danh từ cố định; hay dùng nói đùa về người vụng về","example":"Ein hoffnungsloser Fall.","exampleVi":"Đúng là hết thuốc chữa.","note":"Lời các bạn học bình phẩm về cô bạn hậu đậu.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100037,"sourceUrl":"?kino=kon&part=2"},{"id":"vk_k_on_s01e01_der_tollpatsch","term":"der Tollpatsch","meaning":"người hậu đậu, vụng về","grammar":"Danh từ giống đực; số nhiều: die Tollpatsche","example":"Und ein Tollpatsch.","exampleVi":"Lại còn hậu đậu nữa chứ.","note":"Đi cặp với 'hoffnungsloser Fall' trong cảnh hành lang.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100039,"sourceUrl":"?kino=kon&part=2"},{"id":"vk_k_on_s01e01_leichte_musik","term":"leichte Musik","meaning":"nhạc nhẹ","grammar":"Tính từ đứng trước danh từ không quán từ: leichte Musik","example":"Leichte Musik, Pop und so etwas.","exampleVi":"Nhạc nhẹ, pop và mấy thứ kiểu như vậy.","note":"Tên câu lạc bộ 'Keion' trong bản gốc nghĩa là nhạc nhẹ.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100047,"sourceUrl":"?kino=kon&part=2"},{"id":"vk_k_on_s01e01_faulenzen","term":"faulenzen","meaning":"lười biếng nằm dài, lêu lổng","grammar":"Động từ yếu, sắc thái thông tục","example":"Du kannst doch auch hier faulenzen.","exampleVi":"Cậu cũng có thể nằm lười ở đây mà.","note":"Một trong những 'sở trường' của Yui.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100245,"sourceUrl":"?kino=kon&part=6"},{"id":"vk_k_on_s01e01_umstimmen","term":"umstimmen","meaning":"thuyết phục ai đó đổi ý","grammar":"Động từ tách được tiền tố um-; jdn. umstimmen","example":"Wir müssen sie umstimmen.","exampleVi":"Phải làm cô ấy đổi ý mới được.","note":"Kế hoạch của Ritsu và Mio với Yui.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100218,"sourceUrl":"?kino=kon&part=6"},{"id":"vk_k_on_s01e01_jdm_etwas_beibringen","term":"jdm. etwas beibringen","meaning":"dạy ai đó điều gì","grammar":"Động từ tách được bei-; người học ở Dativ, nội dung ở Akkusativ","example":"Wir werden dir alles beibringen, was wir können.","exampleVi":"Bọn tớ sẽ dạy cậu mọi thứ bọn tớ biết.","note":"Lời hứa của Mio khi rủ Yui học guitar.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100273,"sourceUrl":"?kino=kon&part=7"},{"id":"vk_k_on_s01e01_auf_etwas_stehen","term":"auf etwas stehen","meaning":"mê, khoái thứ gì đó (khẩu ngữ)","grammar":"stehen + auf + Akkusativ; chỉ dùng trong văn nói","example":"Auf alles, was niedlich und süß ist.","exampleVi":"Những thứ xinh xắn, dễ thương ấy.","note":"Cặp hỏi đáp: 'Worauf stehst du?' — 'Ich stehe auf …'","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100236,"sourceUrl":"?kino=kon&part=6"},{"id":"vk_k_on_s01e01_sich_etwas_uberlegen","term":"sich etwas überlegen","meaning":"suy nghĩ lại, đổi ý","grammar":"Phản thân với Dativ: sich (Dat.) etwas überlegen","example":"Ich hab's mir überlegt. Ich will doch Clubmitglied werden.","exampleVi":"Tớ nghĩ lại rồi. Tớ muốn vào câu lạc bộ.","note":"Bước ngoặt cuối tập của Yui.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100260,"sourceUrl":"?kino=kon&part=7"},{"id":"vk_k_on_s01e01_kneifen","term":"kneifen","meaning":"chuồn, né tránh việc gì (lóng)","grammar":"Động từ mạnh thông tục: kneift, kniff, gekniffen","example":"Was? Du willst kneifen?","exampleVi":"Cái gì? Cô muốn chuồn à?","note":"Xuất hiện trong cảnh Yui tưởng tượng bị đàn chị dọa nạt.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100162,"sourceUrl":"?kino=kon&part=5"},{"id":"vk_k_on_s01e01_wenigstens","term":"wenigstens","meaning":"ít nhất, chí ít","grammar":"Trạng từ; làm lời đề nghị nhẹ nhàng hơn","example":"Hör uns wenigstens einmal beim Spielen zu, bevor du gehst, ja?","exampleVi":"Trước khi về, cậu nghe bọn tớ chơi một lần thôi nhé?","note":"Ritsu dùng khi năn nỉ Yui nghe thử một lần.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100252,"sourceUrl":"?kino=kon&part=6"},{"id":"vk_k_on_s01e01_auf_keinen_fall","term":"auf keinen Fall","meaning":"tuyệt đối không","grammar":"Cụm trạng từ nhấn mạnh phủ định; hay đi với dürfen/können","example":"Wir dürfen sie auf keinen Fall einfach so vom Haken lassen.","exampleVi":"Dù thế nào cũng không được để cô ấy vuột mất dễ dàng thế này.","note":"Câu quyết tâm của Ritsu.","deck":"🎬 Video: K-On! – Tập 1","tags":["Video","K-On!"],"videoKey":"k_on_s01e01","cueId":1100216,"sourceUrl":"?kino=kon&part=6"}]};
